PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY, username TEXT NOT NULL COLLATE NOCASE UNIQUE, email TEXT COLLATE NOCASE UNIQUE, password TEXT, rating INTEGER NOT NULL DEFAULT 1200, bio TEXT NOT NULL DEFAULT '', joined TEXT NOT NULL, display_name TEXT NOT NULL DEFAULT '', country TEXT NOT NULL DEFAULT '', avatar TEXT, banner TEXT, private INTEGER NOT NULL DEFAULT 0, wallet_public INTEGER NOT NULL DEFAULT 0, email_verified INTEGER NOT NULL DEFAULT 0, settings TEXT NOT NULL DEFAULT '{}', deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sessions(token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL, created INTEGER NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE wallets(address TEXT PRIMARY KEY COLLATE NOCASE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, primary_wallet INTEGER NOT NULL DEFAULT 0, linked INTEGER NOT NULL);
CREATE INDEX wallets_user ON wallets(user_id);
CREATE TABLE challenges(token TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, purpose TEXT NOT NULL, expires INTEGER NOT NULL, binding TEXT);
CREATE TABLE games(id TEXT PRIMARY KEY, state TEXT NOT NULL, white TEXT NOT NULL REFERENCES users(id), black TEXT REFERENCES users(id), status TEXT NOT NULL, created INTEGER NOT NULL, revision INTEGER NOT NULL DEFAULT 0, rated_applied INTEGER NOT NULL DEFAULT 0, chain_match TEXT UNIQUE);
CREATE INDEX games_white ON games(white,created DESC);
CREATE INDEX games_black ON games(black,created DESC);
CREATE TABLE active_players(user_id TEXT PRIMARY KEY REFERENCES users(id), game_id TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE);
CREATE TABLE moves(game_id TEXT NOT NULL REFERENCES games(id), revision INTEGER NOT NULL, san TEXT NOT NULL, fen TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY(game_id,revision));
CREATE TABLE ratings(user_id TEXT NOT NULL REFERENCES users(id), category TEXT NOT NULL, rating INTEGER NOT NULL DEFAULT 1200, games INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,category));
CREATE TABLE rating_history(game_id TEXT NOT NULL REFERENCES games(id), user_id TEXT NOT NULL REFERENCES users(id), category TEXT NOT NULL, before_rating INTEGER NOT NULL, after_rating INTEGER NOT NULL, at INTEGER NOT NULL, PRIMARY KEY(game_id,user_id));
CREATE TABLE audit(id TEXT PRIMARY KEY, user_id TEXT, action TEXT NOT NULL, at INTEGER NOT NULL, detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE mail_outbox(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, purpose TEXT NOT NULL, url TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, until INTEGER NOT NULL);
CREATE TABLE chain_events(chain_id INTEGER NOT NULL, contract TEXT NOT NULL, tx TEXT NOT NULL, log_index INTEGER NOT NULL, block_number INTEGER NOT NULL, block_hash TEXT NOT NULL, name TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(chain_id,contract,tx,log_index));
CREATE TABLE chain_cursors(chain_id INTEGER NOT NULL, contract TEXT NOT NULL, block_number INTEGER NOT NULL, block_hash TEXT NOT NULL, PRIMARY KEY(chain_id,contract));
CREATE TABLE chain_matches(chain_id INTEGER NOT NULL, contract TEXT NOT NULL, id TEXT NOT NULL, white TEXT NOT NULL, black TEXT NOT NULL, state INTEGER NOT NULL, stake TEXT NOT NULL, token TEXT NOT NULL, updated INTEGER NOT NULL, PRIMARY KEY(chain_id,contract,id));
CREATE TABLE attestations(chain_id INTEGER NOT NULL, contract TEXT NOT NULL, match_id TEXT NOT NULL, nonce TEXT NOT NULL, record_hash TEXT NOT NULL, expiry INTEGER NOT NULL, signature TEXT NOT NULL, PRIMARY KEY(chain_id,contract,match_id,nonce));
CREATE TABLE tournaments(id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','open','active','finished')), starts INTEGER);
CREATE TABLE achievements(id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL);
CREATE TABLE user_achievements(user_id TEXT NOT NULL REFERENCES users(id), achievement_id TEXT NOT NULL REFERENCES achievements(id), game_id TEXT REFERENCES games(id), earned INTEGER NOT NULL, chain_id INTEGER, tx TEXT, PRIMARY KEY(user_id,achievement_id));
